<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bildirimler</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:850px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:12px;padding:16px;margin:12px 0}.muted{color:#6d796f;font-size:13px}.unread{border-left:4px solid #176b50}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1>Bildirimler</h1><?php foreach($notifications as $notice): ?><article class="item <?= $notice['read_at']?'':'unread' ?>"><strong><?= e($notice['title']) ?></strong><p><?= e($notice['body']) ?></p><div class="muted"><?= e($notice['created_at']) ?></div></article><?php endforeach; ?><?php if(!$notifications): ?><p>Henüz bildiriminiz yok.</p><?php endif; ?><p><a href="<?= e(app_url('/')) ?>">Ana sayfa</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>